package cn.song.mybatisplus.visualizer.ui.highlight

import cn.song.mybatisplus.visualizer.ui.highlight.DatabaseSchemaResolver.DasAccessors
import cn.song.mybatisplus.visualizer.ui.highlight.DatabaseSchemaResolver.ModelTraversal
import org.junit.After
import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Before
import org.junit.Test

/**
 * O-59 T-IIR-02：`DatabaseSchemaResolver.ColumnMeta.autoGenerated` 的解析与收录口径。
 *
 * 判据来源（javap 实证，本机 2026-09-22）：`DasTable.getColumnAttrs(DasColumn)` 返回
 * `Set<DasColumn$Attribute>`，枚举常量名即 `AUTO_GENERATED`；生产链经反射读取
 * （`Method` 从**声明类** DasTable 取，遵 T-Embed-10 跨 classloader 教训）。
 *
 * 本单测经 [DatabaseSchemaResolver.traversalForTest] 注入遍历替身，验的是**收录条件与透传**这一半；
 * 生产反射读的那一半只能在有真实数据源的环境验（O-59 计划 §五-1 的真机走查项）。
 */
class DatabaseSchemaResolverAutoGeneratedTest {

    private class FakeNs(val nsName: String, val up: Any? = null)
    private class FakeTable(val tableName: String, val columns: List<String>, val up: Any? = null)
    private class FakeColumn(val columnName: String, val comment: String?)

    /** 只有名为 `id` 的列是自增；其余列三项元数据皆空（走「稀疏表」口径）。 */
    private val accessors = DasAccessors(
        isTable = { it is FakeTable },
        isColumn = { it is FakeColumn },
        name = {
            when (it) {
                is FakeTable -> it.tableName
                is FakeColumn -> it.columnName
                is FakeNs -> it.nsName
                else -> null
            }
        },
        comment = { (it as? FakeColumn)?.comment },
        children = { (it as? FakeTable)?.columns?.map { c -> FakeColumn(c, null) } },
        // 祖先链必须同时覆盖表与库/模式节点（照 DatabaseSchemaResolverSchemaScopeTest 的替身）——
        // 只给表节点会让链在 "public" 处断掉，库名判成 "public" ≠ 替身库名 → 表根本不被命中。
        parent = {
            when (it) {
                is FakeTable -> it.up
                is FakeNs -> it.up
                else -> null
            }
        },
        typeSpec = { null },
        notNull = { null },
        autoGenerated = { _, col -> (col as? FakeColumn)?.columnName == "id" },
    )

    @Before
    fun setUp() {
        DatabaseSchemaResolver.traversalForTest = null
        DatabaseSchemaResolver.dataSourceDatabaseForTest = null
        DatabaseSchemaResolver.invalidateAll()
        DatabaseSchemaResolver.clearNegativeCache()
    }

    @After
    fun tearDown() {
        DatabaseSchemaResolver.traversalForTest = null
        DatabaseSchemaResolver.dataSourceDatabaseForTest = null
    }

    private fun stubModel() {
        DatabaseSchemaResolver.dataSourceDatabaseForTest = { "mpj_demo" }
        DatabaseSchemaResolver.traversalForTest = {
            ModelTraversal(
                listOf(FakeTable("t_ag", listOf("id", "plain"), FakeNs("public", FakeNs("mpj_demo")))),
                accessors,
            )
        }
    }

    /**
     * 自增列**即使注释/类型/NOT NULL 三项皆空也必须收录**——否则它落不进这份稀疏表，
     * 回滚侧 identity 包装就取不到列名（T-Round10 独立复核 blocker② 的形态）。
     */
    @Test
    fun `自增列即使三项元数据皆空也必须收录并带标记`() {
        stubModel()
        val meta = DatabaseSchemaResolver.resolveFromSources("t_ag", listOf(Any()))
        assertEquals(
            "自增列必须进这份稀疏表且带 autoGenerated=true",
            true,
            meta.columns["id"]?.autoGenerated,
        )
        assertFalse(
            "三项皆空且非自增的列仍按原口径不收录（收录条件只放宽了自增一项）",
            meta.columns.containsKey("plain"),
        )
    }

    /** 对照：同一个替身下，非自增列即使被收录也不得被标成自增（防「一律 true」的过报）。 */
    @Test
    fun `非自增列不得被标成自增`() {
        DatabaseSchemaResolver.dataSourceDatabaseForTest = { "mpj_demo" }
        val withComment = DasAccessors(
            isTable = { it is FakeTable },
            isColumn = { it is FakeColumn },
            name = {
                when (it) {
                    is FakeTable -> it.tableName
                    is FakeColumn -> it.columnName
                    is FakeNs -> it.nsName
                    else -> null
                }
            },
            comment = { (it as? FakeColumn)?.comment ?: "有注释" },
            children = { (it as? FakeTable)?.columns?.map { c -> FakeColumn(c, "有注释") } },
            parent = {
                when (it) {
                    is FakeTable -> it.up
                    is FakeNs -> it.up
                    else -> null
                }
            },
            typeSpec = { "int(11)" },
            notNull = { false },
            autoGenerated = { _, _ -> false },
        )
        DatabaseSchemaResolver.traversalForTest = {
            ModelTraversal(listOf(FakeTable("t_plain", listOf("id"), FakeNs("public", FakeNs("mpj_demo")))), withComment)
        }
        val meta = DatabaseSchemaResolver.resolveFromSources("t_plain", listOf(Any()))
        assertTrue("有注释的列本就收录", meta.columns.containsKey("id"))
        assertEquals("accessor 说不是自增就必须是 false（不得过报）", false, meta.columns["id"]?.autoGenerated)
    }
}
